// PiSDR faceplate. Print as modelled: front face down on the bed, bosses pointing up.
include <pisdr_params.scad>

module faceplate() {
    difference() {
        union() {
            // plate
            linear_extrude(face_t) rounded_rect([outer_w, outer_h], 4);
            // alignment rim that nests inside the shell walls
            translate([0, 0, face_t - eps])
                linear_extrude(3 + eps) difference() {
                    offset(delta = -(wall + fit_clear)) square([outer_w, outer_h]);
                    offset(delta = -(wall + fit_clear + 1.5)) square([outer_w, outer_h]);
                }
            // corner bosses, full interior depth, heat-set inserts for screws from the back
            for (p = boss_xy) translate([p[0], p[1], face_t - eps])
                cylinder(d = boss_d, h = interior_depth + eps);
            // display pocket: L-shaped locator tabs at the module corners
            display_tabs();
            // encoder anti-rotation pillars bracketing the module PCB
            encoder_pillars();
            // key carrier screw bosses
            for (x = carrier_screw_x) translate([x, key_y, face_t - eps])
                cylinder(d = 6, h = 3 + eps);
        }
        // screen window with a 1 mm chamfer on the front edge
        translate([window_x0, window_y0, -eps]) hull() {
            translate([-1, -1, 0]) linear_extrude(eps) square([window_w + 2, window_h + 2]);
            translate([0, 0, 1]) linear_extrude(face_t + 1) square([window_w, window_h]);
        }
        // glass relief: let the touch glass sit flush if it overhangs the frame
        if (display_glass_t > 0)
            translate([display_x - display_clear, display_y - display_clear, face_t - display_glass_t])
                cube([display_w + 2 * display_clear, display_h + 2 * display_clear, display_glass_t + 10]);
        // heat-set insert holes in the bosses (from the back)
        for (p = boss_xy) translate([p[0], p[1], face_t + interior_depth - insert_depth])
            cylinder(d = insert_hole_d, h = insert_depth + 1);
        // encoder bushing hole + local thinning so the nut reaches
        translate([knob_cx, knob_cy, -eps]) cylinder(d = enc_bushing_d, h = face_t + 1);
        thin_t = max(0, face_t - (enc_bushing_len - 2.5));
        if (thin_t > 0)
            translate([knob_cx, knob_cy, face_t - thin_t]) cylinder(d = 14, h = thin_t + 1);
        // keycap holes
        for (x = key_centres_x) translate([x, key_y, -eps])
            linear_extrude(face_t + 1) square(keycap_hole, center = true);
        // key carrier screws (self-tapping M2.5)
        for (x = carrier_screw_x) translate([x, key_y, 0.8])
            cylinder(d = carrier_screw_d, h = face_t + 3);
        // engraved label on the knob column, below the knob
        if (label_text != "")
            translate([knob_cx, knob_cy - knob_d / 2 - 7, -eps])
                linear_extrude(label_depth + eps)
                    mirror([1, 0, 0])   // engraved into the front face, readable from the front
                        text(label_text, size = label_size, halign = "center", valign = "center");
