// PiSDR rear shell: four side walls + back wall, open towards the faceplate.
// Modelled in the assembled frame; the last line stands it on its back wall for printing.
include <pisdr_params.scad>

shell_depth = interior_depth + rear_t;      // from the faceplate rear to the outside of the back

module rear_shell() {
    difference() {
        union() {
            // walls + back
            into(face_t) difference() {
                linear_extrude(shell_depth) rounded_rect([outer_w, outer_h], 4);
                translate([0, 0, -eps]) linear_extrude(interior_depth + eps)
                    offset(delta = -wall) square([outer_w, outer_h]);
            }
            // corner screw pads on the inside of the back wall (thicker seat for the countersink)
            for (p = boss_xy) into(z_back_inner - 1.5) translate([p[0], p[1], 0])
                cylinder(d = boss_d + 2, h = 1.5 + eps);
            display_posts();
            v4_cradle();
        }
        // countersunk M3 holes through the back wall into the faceplate bosses
        for (p = boss_xy) {
            into(z_back_inner - 2) translate([p[0], p[1], 0]) cylinder(d = m3_clear_d, h = rear_t + 3);
            into(depth_total - 1.8) translate([p[0], p[1], 0])
                cylinder(d1 = m3_clear_d, d2 = m3_csk_d + 0.4, h = 1.8 + eps);
        }
        // SMA bulkhead on the right wall
        into(sma_pos[1]) translate([outer_w - wall - 1, wall + sma_pos[0], 0]) rotate([0, 90, 0])
            d_hole(sma_hole_d, wall + 2, sma_flat);
        // bottom-wall connectors
        if (usbc_panel) into(panel_conn_z) translate([usbc_x, -1, 0]) rotate([-90, 0, 0]) {
            hull() for (sx = [-1, 1]) translate([sx * (usbc_opening[0] - usbc_opening[1]) / 2, 0, 0])
                cylinder(d = usbc_opening[1], h = wall + 2);
            for (sx = [-1, 1]) translate([sx * usbc_screw_spacing / 2, 0, 0])
                cylinder(d = usbc_screw_d, h = wall + 2);
        }
        if (audio_jack) into(panel_conn_z) translate([audio_x, -1, 0]) rotate([-90, 0, 0])
            cylinder(d = audio_hole_d, h = wall + 2);
        // backlight button access
        if (len(bl_button_pos) == 2)
            into(z_back_inner - 1) translate([display_x + bl_button_pos[0], display_y + bl_button_pos[1], 0])
                cylinder(d = bl_button_d, h = rear_t + 2);
        // vents in the back wall over the Pi
        vents_back();
        // vents in the top wall
        for (i = [0:vent_cols - 1])
            into(face_t + interior_depth / 2 - vent_slot[1] / 4)
                translate([display_x + 30 + i * vent_pitch - vent_slot[0] / 2, outer_h - wall - 1, 0])
                    cube([vent_slot[0], wall + 2, vent_slot[1] / 2]);
    }
}

module d_hole(d, h, flat) {
    // cylinder along +Z with an optional D flat for anti-rotation bulkheads
    difference() {
        cylinder(d = d, h = h);
        if (flat) translate([d / 2 - 0.6, -d, -1]) cube([d, 2 * d, h + 2]);
    }
}

module display_posts() {
    // Press the display module forward against the faceplate lip. Tips get a dab of
    // silicone or a felt pad; the length is derived so they just touch the module rear.
    post_len = z_back_inner - post_tip_z;
    for (p = post_xy) into(post_tip_z) translate([p[0], p[1], 0]) {
        cylinder(d = post_d, h = post_len + eps);
        cylinder(d1 = 4, d2 = post_d, h = 1.5);
    }
}

module v4_cradle() {
    // Two saddles hold the dongle against the back wall; a zip tie goes through the slots.
    inner_w = v4_size[0] + 2 * v4_clear;
    saddle_h = v4_size[2] * 0.75;
    for (yy = [v4_y0_abs + 12, v4_y0_abs + v4_size[1] - 12])
        into(z_back_inner - saddle_h) translate([knob_cx, yy, 0])
            difference() {
                translate([-(inner_w / 2 + 3), -2, 0]) cube([inner_w + 6, 4, saddle_h + eps]);
                translate([-inner_w / 2, -3, -eps]) cube([inner_w, 6, saddle_h + 1]);
                // zip-tie slots
                for (sx = [-1, 1]) translate([sx * (inner_w / 2 + 1.5), 0, saddle_h / 2])
                    cube([1.6, 5, 3.5], center = true);
            }
    // end stop so the dongle cannot slide towards the bottom wall
    into(z_back_inner - saddle_h) translate([knob_cx - inner_w / 2, v4_y0_abs - 3, 0])
        cube([inner_w, 3, saddle_h + eps]);
}

module vents_back() {
    // slot array over the Pi footprint, avoiding the display posts
    cx = pi_x0 + pi_w / 2;
    cy = pi_y0 + pi_h / 2;
    for (i = [0:vent_cols - 1])
        into(z_back_inner - 1) translate([cx - (vent_cols - 1) * vent_pitch / 2 + i * vent_pitch, cy, 0])
            linear_extrude(rear_t + 2) square([vent_slot[0], vent_slot[1]], center = true);
}

echo_summary();
// Print orientation: back wall on the bed, opening up.
translate([0, 0, depth_total]) rear_shell();

// PiSDR tuning knob for the EC11 module shaft (6 mm D-shaft or knurled).
// Printed upright: shaft socket down. Add a drop of hot glue or a M3 grub screw (hole provided).
include <pisdr_params.scad>

grub_screw = true;      // M3 grub screw hole into the shaft flat
grub_d     = 2.8;       // tap M3 directly into the plastic
ridges     = 24;        // finger grip ridges around the skirt
dimple     = true;      // finger dimple on top for fast spinning

socket_d     = enc_shaft_d + 0.3;
socket_depth = min(enc_shaft_len - 1.0, knob_h - 3.0);

module knob() {
    difference() {
        union() {
            // body with a slight taper and a rounded top edge
            hull() {
                cylinder(d = knob_d, h = 1);
                translate([0, 0, knob_h - 2]) rotate_extrude() translate([knob_d / 2 - 2.5, 0]) circle(r = 2);
            }
            // grip ridges
            for (i = [0:ridges - 1]) rotate(i * 360 / ridges)
                translate([knob_d / 2 - 0.6, 0, 1.5]) cylinder(d = 1.6, h = knob_h - 5, $fn = 12);
        }
        // shaft socket with D flat
        translate([0, 0, -eps]) difference() {
            cylinder(d = socket_d, h = socket_depth + eps);
            if (enc_shaft_flat < enc_shaft_d)
                translate([-socket_d, enc_shaft_flat - enc_shaft_d / 2 + 0.15, -1]) cube([2 * socket_d, socket_d, socket_depth + 2]);
        }
        // grub screw, perpendicular to the flat
        if (grub_screw) translate([0, 0, socket_depth / 2]) rotate([-90, 0, 0]) cylinder(d = grub_d, h = knob_d);
        // finger dimple
        if (dimple) translate([knob_d / 4, 0, knob_h + 2.5]) sphere(r = 4.5);
        // pointer line
        translate([knob_d / 2 - 6, -0.6, knob_h - 0.8]) cube([5, 1.2, 1]);
    }
}

knob();

// PiSDR keycaps for the four 12 mm tactile switches. Printed top-down (as modelled).
// The square skirt rides in the faceplate hole, the flange behind the faceplate stops the
// cap falling out, and the plunger of the switch sits in the socket underneath.
include <pisdr_params.scad>

skirt_len = keycap_proud + face_t;                 // from the top face to the faceplate rear
cap_total = skirt_len + keycap_rest_gap + keycap_flange_t;

module keycap(legend = "") {
    difference() {
        union() {
            // skirt + visible top (slightly rounded top edge)
            hull() {
                translate([0, 0, 0.8]) linear_extrude(skirt_len - 0.8) square(keycap_top, center = true);
                linear_extrude(0.8) square(keycap_top - 1.6, center = true);
            }
            // flange
            translate([0, 0, skirt_len + keycap_rest_gap]) linear_extrude(keycap_flange_t)
                square(keycap_flange, center = true);
            // solid between skirt and flange (fills the rest gap)
            translate([0, 0, skirt_len - eps]) linear_extrude(keycap_rest_gap + 2 * eps)
                square(keycap_top, center = true);
        }
        // plunger socket from the back
        translate([0, 0, cap_total - keycap_socket_depth]) cylinder(d = key_plunger_d + 0.3, h = keycap_socket_depth + 1);
        // optional engraved legend on the top face
        if (legend != "") translate([0, 0, -eps]) linear_extrude(0.5) mirror([1, 0, 0])
            text(legend, size = 5, halign = "center", valign = "center");
    }
}

// Four caps laid out for printing; legends are optional since the screen labels the keys.
for (i = [0:3]) translate([i * (keycap_flange + 4), 0, 0]) keycap();

// PiSDR key carrier: a spacer plate between the faceplate and the key perfboard.
// It sets the switch-to-faceplate distance exactly, keeps the four switches on the soft-key
// centres, and doubles as the drilling/soldering template for the perfboard.
//
//   faceplate rear | carrier (carrier_t thick) | perfboard (switches soldered on its front)
//
// Print flat as modelled (faceplate side down).
include <pisdr_params.scad>

body_pocket = key_body + 0.6;          // switch body passes through
flange_pocket = keycap_flange + 0.6;   // keycap flange floats in here
flange_pocket_depth = keycap_rest_gap + keycap_flange_t + 0.4;

module carrier() {
    difference() {
        linear_extrude(carrier_t) rounded_rect([carrier_len, carrier_w], 3);
        for (x = key_centres_x) translate([x - carrier_x0, carrier_w / 2, 0]) {
            // flange pocket on the faceplate side
            translate([0, 0, -eps]) linear_extrude(flange_pocket_depth + eps) square(flange_pocket, center = true);
            // body opening right through
            translate([0, 0, -eps]) linear_extrude(carrier_t + 1) square(body_pocket, center = true);
        }
        // screws to the faceplate (M2.5 through perfboard + carrier into the faceplate)
        for (x = carrier_screw_x) translate([x - carrier_x0, carrier_w / 2, -eps])
            cylinder(d = carrier_screw_clear, h = carrier_t + 1);
        // perfboard drill template: pilot dimples at the switch pin positions (12 x 12 THT: 5.0 x 12.5 mm)
        for (x = key_centres_x) for (sx = [-1, 1], sy = [-1, 1])
            translate([x - carrier_x0 + sx * 2.5, carrier_w / 2 + sy * 6.25, carrier_t - 1])
                cylinder(d = 1.2, h = 2);
    }
}

echo(str("carrier thickness ", carrier_t, " mm; screw holes at X = ", carrier_screw_x));
carrier();

// PiSDR test coupon - print this BEFORE the full enclosure.
// A 60 x 45 mm slice of the faceplate containing: one window corner with its lip and
// display locator tab, one keycap hole, the encoder bushing hole with its thinning, a
// corner boss with the heat-set insert hole and a carrier screw hole. Check:
//   * the display corner drops between the tabs with light friction,
//   * a keycap slides in the hole without binding,
//   * the EC11 nut tightens on the bushing through the panel,
//   * the heat-set insert seats and an M3 screw threads in.
include <pisdr_params.scad>

coupon = [60, 45];

module coupon_part() {
    difference() {
        union() {
            linear_extrude(face_t) rounded_rect(coupon, 3);
            // display corner tabs (bottom-left corner of the module placed at [8, 8])
            translate([8 - display_clear - 1.5, 8 - display_clear - 1.5, face_t - eps]) linear_extrude(6) {
                square([1.5, 14]);
                square([14, 1.5]);
            }
            // corner boss
            translate([52, 37, face_t - eps]) cylinder(d = boss_d, h = 12);
            // carrier screw boss
            translate([50, 8, face_t - eps]) cylinder(d = 6, h = 3);
        }
        // window corner: lip = window_margin inside the module edge
        translate([8 + (active_off_left - window_margin), 8 + (active_off_bottom - window_margin), -eps])
            hull() {
                translate([-1, -1, 0]) linear_extrude(eps) square([40, 30]);
                translate([0, 0, 1]) linear_extrude(face_t + 1) square([39, 29]);
            }
        // keycap hole
